// Manacher O(n) longest palindromic substring
string t = "^#";
for (char c : s) { t += c; t += "#"; }
t += "$";
vector<int> p(t.size(), 0);
int c = 0, r = 0;                       // center, right edge
for (int i = 1; i < t.size() - 1; i++) {
    int mirror = 2 * c - i;
    if (i < r) p[i] = min(r - i, p[mirror]);   // mirrored head start
    while (t[i + p[i] + 1] == t[i - p[i] - 1]) p[i]++;
    if (i + p[i] > r) { c = i; r = i + p[i]; }
}
// max p[i] gives radius; original index math from transform
